"use client";import{useState}from"react";import{api,uuidv7}from"../../lib/api";export default function Approve(){const[id,setId]=useState("");const[message,setMessage]=useState("");async function submit(){const r=await api(`/api/v1/schedules/${id}/approve`,{method:"POST",headers:{"idempotency-key":uuidv7()},body:"{}"});setMessage(JSON.stringify(r.data??{error:r.error},null,2))}return <main className="route"><p className="eyebrow">ADMIN REVIEW</p><h1>Approve proposal</h1><input placeholder="Validated schedule UUID" value={id} onChange={e=>setId(e.target.value)}/><button className="primary" onClick={submit}>Approve <span>→</span></button>{message&&<pre>{message}</pre>}</main>}
